// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
"use client";

import * as React from "react";
import { cn } from "./utils";
import { XIcon } from "lucide-react";
import { Dialog as DialogPrimitive } from "./primitive-dialog";

import { Button } from "./button";

function Dialog({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Root>) {
  return <DialogPrimitive.Root data-slot="dialog" {...props} />;
}

function DialogTrigger({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Trigger>) {
  return <DialogPrimitive.Trigger data-slot="dialog-trigger" {...props} />;
}

function DialogPortal({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Portal>) {
  return <DialogPrimitive.Portal data-slot="dialog-portal" {...props} />;
}

function DialogClose({
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Close>) {
  return <DialogPrimitive.Close data-slot="dialog-close" {...props} />;
}

function DialogOverlay({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Overlay>) {
  return (
    <DialogPrimitive.Overlay
      data-slot="dialog-overlay"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DialogContent({
  className,
  children,
  showCloseButton = true,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Content> & {
  showCloseButton?: boolean;
}) {
  return (
    <DialogPortal data-slot="dialog-portal">
      <DialogOverlay />
      <DialogPrimitive.Content
        data-slot="dialog-content"
        className={cn("roc-ui", className)}
        {...props}
      >
        {children}
        {showCloseButton && (
          <DialogPrimitive.Close
            data-slot="dialog-close"
            className="roc-ui roc-ui-dialog-dismiss"
          >
            <XIcon />
            <span className="roc-ui-sr-only">Close</span>
          </DialogPrimitive.Close>
        )}
      </DialogPrimitive.Content>
    </DialogPortal>
  );
}

function DialogHeader({ className, ...props }: React.ComponentProps<"div">) {
  return (
    <div
      data-slot="dialog-header"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DialogFooter({
  className,
  showCloseButton = false,
  children,
  ...props
}: React.ComponentProps<"div"> & {
  showCloseButton?: boolean;
}) {
  return (
    <div
      data-slot="dialog-footer"
      className={cn("roc-ui", className)}
      {...props}
    >
      {children}
      {showCloseButton && (
        <DialogPrimitive.Close asChild>
          <Button variant="outline">Close</Button>
        </DialogPrimitive.Close>
      )}
    </div>
  );
}

function DialogTitle({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Title>) {
  return (
    <DialogPrimitive.Title
      data-slot="dialog-title"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

function DialogDescription({
  className,
  ...props
}: React.ComponentProps<typeof DialogPrimitive.Description>) {
  return (
    <DialogPrimitive.Description
      data-slot="dialog-description"
      className={cn("roc-ui", className)}
      {...props}
    />
  );
}

export {
  Dialog,
  DialogClose,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogOverlay,
  DialogPortal,
  DialogTitle,
  DialogTrigger,
};

import "./dialog.css";

import { clsx, type ClassValue } from "clsx";
/** Scoped CSS needs no Tailwind runtime or host configuration. */
export function cn(...inputs: ClassValue[]) {
  return clsx(inputs);
}

"use client";
// ROC primitive: a modal dialog. Behaviour from Base UI, shaped for ROC.
import { Dialog as Base } from "@animate-ui/react/primitives/base-ui/dialog";
import { createDialog } from "./primitive-dialog-core";

export const Dialog = createDialog(Base);

"use client";
// ROC primitive: shared adapter that gives Base UI's Dialog parts (and Alert Dialog's,
// which share them) the Overlay/Content/Close shape ROC components use.
import * as React from "react";
import { isNativeButton } from "./primitive-popup";
import { renderChild } from "./primitive-popup";

type Props<T extends keyof React.JSX.IntrinsicElements> = Omit<
  React.ComponentProps<T>,
  "ref"
> & { ref?: React.Ref<any> };

export function createDialog(Base: any) {
  function Root({
    open,
    defaultOpen,
    onOpenChange,
    modal = true,
    children,
  }: {
    open?: boolean;
    defaultOpen?: boolean;
    onOpenChange?: (open: boolean) => void;
    modal?: boolean;
    children?: React.ReactNode;
  }) {
    return (
      <Base.Root
        open={open}
        defaultOpen={defaultOpen}
        modal={modal}
        onOpenChange={(next: boolean) => onOpenChange?.(next)}
      >
        {children}
      </Base.Root>
    );
  }

  /** A button that renders as its own child when `asChild` is set. */
  function ButtonPart(Part: any, withState: boolean) {
    return function Part_({
      asChild,
      children,
      ...props
    }: Props<"button"> & { asChild?: boolean }) {
      if (asChild && React.isValidElement(children)) {
        const child = children as React.ReactElement;
        return (
          <Part
            {...(props as object)}
            nativeButton={isNativeButton(child)}
            render={
              withState ? renderChild(child, (state) => state.open) : child
            }
          />
        );
      }
      return withState ? (
        <Part
          {...(props as object)}
          render={(p: Record<string, any>, state: { open: boolean }) => (
            <button {...p} data-state={state.open ? "open" : "closed"} />
          )}
        >
          {children}
        </Part>
      ) : (
        <Part {...(props as object)}>{children}</Part>
      );
    };
  }

  const Trigger = ButtonPart(Base.Trigger, true);
  const Close = ButtonPart(Base.Close, false);

  function Overlay(props: Props<"div">) {
    return (
      <Base.Backdrop
        data-roc-motion="animate-ui"
        {...props}
        render={(p: Record<string, any>, state: { open: boolean }) => (
          <div {...p} data-state={state.open ? "open" : "closed"} />
        )}
      />
    );
  }

  function Content({
    initialFocus,
    children,
    ...props
  }: Props<"div"> & { initialFocus?: React.RefObject<HTMLElement | null> }) {
    return (
      <Base.Popup
        data-roc-motion="animate-ui"
        {...props}
        initialFocus={initialFocus}
        render={(p: Record<string, any>, state: { open: boolean }) => (
          <div {...p} data-state={state.open ? "open" : "closed"} />
        )}
      >
        {children}
      </Base.Popup>
    );
  }

  return {
    Root,
    Trigger,
    Portal: Base.Portal as React.ComponentType<
      { children?: React.ReactNode; container?: HTMLElement | null } & Record<string, unknown>
    >,
    Overlay,
    Content,
    Close,
    Title: Base.Title as React.ComponentType<Props<"h2">>,
    Description: Base.Description as React.ComponentType<Props<"p">>,
  };
}

"use client";
// ROC primitive: shared adapter that gives Base UI's Portal > Positioner > Popup
// parts the shape ROC components use: a single `Content`, `asChild` triggers,
// `data-state`, and the `--roc-popup-*` variables.
import * as React from "react";
import { mergeProps } from "@base-ui/react/merge-props";
import { composeRefs } from "./primitive-utils";

export type Side = "top" | "right" | "bottom" | "left";
export type Align = "start" | "center" | "end";

export type PositionProps = {
  side?: Side;
  align?: Align;
  sideOffset?: number;
  alignOffset?: number;
  collisionPadding?: number;
  /** Set false to keep the popup on its requested side even when it overflows. */
  avoidCollisions?: boolean;
  /** Keep the popup in view while the trigger scrolls out ("always"). */
  sticky?: "partial" | "always";
};

/** Render `child` with Base UI's props merged in, plus `data-state`. */
export function renderChild(
  child: React.ReactElement,
  open: (state: any) => boolean,
  openValue = "open",
  extra?: (state: any) => Record<string, any>,
) {
  return (props: Record<string, any>, state: any) =>
    React.cloneElement(
      child,
      mergeProps(child.props as Record<string, any>, props, {
        "data-state": open(state) ? openValue : "closed",
        ...extra?.(state),
      }) as Record<string, any>,
    );
}

/** Triggers must opt out of native-button behaviour when they render something else. */
export const isNativeButton = (child: React.ReactElement) =>
  typeof child.type !== "string" || child.type === "button";

/** Base UI reports logical sides for submenus; ROC CSS and components use physical ones. */
export function physicalSide(side: string | undefined) {
  if (side !== "inline-start" && side !== "inline-end") return side;
  const rtl =
    typeof document !== "undefined" && document.documentElement.dir === "rtl";
  return (side === "inline-end") !== rtl ? "right" : "left";
}

/** A popup copies its own z-index to the positioner, so stacking matches the CSS. */
function useStackingOf(ref: React.RefObject<HTMLElement | null>) {
  const [zIndex, setZIndex] = React.useState<string>();
  React.useLayoutEffect(() => {
    if (!ref.current) return;
    const value = getComputedStyle(ref.current).zIndex;
    setZIndex(value === "auto" ? undefined : value);
  });
  return zIndex;
}

type Parts = { Positioner: React.ElementType; Popup: React.ElementType };

/**
 * Build a Content component. `prefix` names the CSS variables that ROC and shadcn CSS
 * reads (`--roc-<prefix>-content-transform-origin` and friends).
 */
export function createContent(parts: Parts, prefix: string, openValue = "open") {
  type Props = Omit<React.ComponentProps<"div">, "ref"> &
    PositionProps & {
      ref?: React.Ref<HTMLDivElement>;
      anchor?: Element | null;
      /** Extra props for Base UI's Positioner, such as `alignItemWithTrigger`. */
      positionerProps?: Record<string, unknown>;
      /** Keep mounted while closed. Not needed: Portal handles presence. */
      forceMount?: boolean;
    };
  return function Content({
    side,
    align,
    sideOffset,
    alignOffset,
    collisionPadding = 12,
    avoidCollisions = true,
    sticky,
    anchor,
    positionerProps,
    forceMount: _forceMount,
    style,
    ref,
    children,
    ...props
  }: Props) {
    const popup = React.useRef<HTMLDivElement | null>(null);
    const stacking = useStackingOf(popup);
    return (
      <parts.Positioner
        side={side}
        align={align}
        sideOffset={sideOffset}
        alignOffset={alignOffset}
        collisionPadding={collisionPadding}
        collisionAvoidance={
          avoidCollisions ? undefined : { side: "none", align: "none" }
        }
        sticky={sticky === "always"}
        anchor={anchor ?? undefined}
        {...positionerProps}
        style={{ zIndex: stacking }}
      >
        <parts.Popup
          data-roc-motion="animate-ui"
          {...props}
          ref={composeRefs(ref, popup)}
          render={(popupProps: Record<string, any>, state: { open: boolean }) => (
            <div
              {...popupProps}
              data-side={physicalSide(popupProps["data-side"])}
              data-state={state.open ? openValue : "closed"}
            />
          )}
          style={
            {
              [`--roc-${prefix}-content-transform-origin`]: "var(--transform-origin)",
              [`--roc-${prefix}-content-available-height`]: "var(--available-height)",
              [`--roc-${prefix}-content-available-width`]: "var(--available-width)",
              [`--roc-${prefix}-trigger-width`]: "var(--anchor-width)",
              [`--roc-${prefix}-trigger-height`]: "var(--anchor-height)",
              ...style,
            } as React.CSSProperties
          }
        >
          {children}
        </parts.Popup>
      </parts.Positioner>
    );
  };
}

"use client";
// ROC primitive helpers. Small, dependency-free building blocks.
import * as React from "react";

/** Run the caller's handler first; run ours unless the caller prevented default. */
export function composeEventHandlers<E extends { defaultPrevented: boolean }>(
  original: ((event: E) => void) | undefined,
  ours: ((event: E) => void) | undefined,
) {
  return (event: E) => {
    original?.(event);
    if (!event.defaultPrevented) ours?.(event);
  };
}

type PossibleRef<T> = React.Ref<T> | undefined;

/** Merge refs, forwarding React 19 ref cleanups. */
export function composeRefs<T>(...refs: PossibleRef<T>[]): React.RefCallback<T> {
  return (node) => {
    const cleanups: Array<() => void> = [];
    for (const ref of refs) {
      if (typeof ref === "function") {
        const cleanup = ref(node);
        cleanups.push(
          typeof cleanup === "function" ? cleanup : () => ref(null),
        );
      } else if (ref) {
        (ref as React.RefObject<T | null>).current = node;
        cleanups.push(() => {
          (ref as React.RefObject<T | null>).current = null;
        });
      }
    }
    return () => cleanups.forEach((cleanup) => cleanup());
  };
}

export function useComposedRefs<T>(...refs: PossibleRef<T>[]) {
  // eslint-disable-next-line react-hooks/exhaustive-deps
  return React.useCallback(composeRefs(...refs), refs);
}

export function usePrevious<T>(value: T) {
  const ref = React.useRef({ value, previous: value });
  return React.useMemo(() => {
    if (ref.current.value !== value) {
      ref.current.previous = ref.current.value;
      ref.current.value = value;
    }
    return ref.current.previous;
  }, [value]);
}

// Adapted from shadcn/ui (MIT). See SHADCN-LICENSE.txt and upstream provenance.
import * as React from "react";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "./utils";
import { Button as AnimatedButton } from "@animate-ui/react/primitives/buttons/button";

const buttonVariants = cva("roc-ui roc-ui-button", {
  variants: {
    variant: {
      default: "roc-ui-button-variant-default",
      destructive: "roc-ui-button-variant-destructive",
      outline: "roc-ui-button-variant-outline",
      secondary: "roc-ui-button-variant-secondary",
      ghost: "roc-ui-button-variant-ghost",
      link: "roc-ui-button-variant-link",
    },
    size: {
      default: "roc-ui-button-size-default",
      xs: "roc-ui-button-size-xs",
      sm: "roc-ui-button-size-sm",
      lg: "roc-ui-button-size-lg",
      icon: "roc-ui-button-size-icon",
      "icon-xs": "roc-ui-button-size-icon-xs",
      "icon-sm": "roc-ui-button-size-icon-sm",
      "icon-lg": "roc-ui-button-size-icon-lg",
    },
  },
  defaultVariants: {
    variant: "default",
    size: "default",
  },
});

function Button({
  className,
  variant = "default",
  size = "default",
  asChild = false,
  type,
  children,
  disabled,
  pending = false,
  pendingLabel,
  ...props
}: React.ComponentProps<"button"> &
  VariantProps<typeof buttonVariants> & {
    pending?: boolean;
    pendingLabel?: React.ReactNode;
    asChild?: boolean;
  }) {
  const Comp: React.ElementType = AnimatedButton;

  return (
    <Comp
      asChild={asChild}
      tapScale={disabled || pending ? 1 : 0.97}
      type={asChild ? type : (type ?? "button")}
      data-slot="button"
      data-variant={variant}
      data-size={size}
      className={cn("roc-ui", buttonVariants({ variant, size, className }))}
      {...props}
      disabled={disabled || pending}
      aria-busy={pending || undefined}
    >
      {asChild || pendingLabel === undefined ? (
        children
      ) : (
        <span className="roc-ui-button-label">
          <span
            aria-hidden={pending}
            data-state={pending ? "inactive" : "active"}
          >
            {children}
          </span>
          <span
            aria-hidden={!pending}
            data-state={pending ? "active" : "inactive"}
          >
            {pendingLabel}
          </span>
        </span>
      )}
    </Comp>
  );
}

export { Button, buttonVariants };

import "./button.css";

@import "./ui-base.css";
.roc-ui-button {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  gap: var(--roc-space-2, 8px);
  min-height: var(--roc-control-height, 36px);
  padding: 8px 15px;
  border: 1px solid transparent;
  border-radius: var(--roc-button-radius, var(--roc-radius-control));
  font-family: var(--roc-font-control, inherit);
  font-weight: var(--roc-weight-control, 500);
  cursor: pointer;
  white-space: nowrap;
  text-decoration: none;
  transition:
    background-color var(--roc-motion-quick) ease-out,
    box-shadow var(--roc-motion-quick) ease-out;
}
/* Keep the shared .roc-ui font reset from changing text button height. */
.roc-ui.roc-ui-button {
  line-height: 1.2;
}
.roc-ui-button.roc-ui-button-variant-default {
  background: var(--roc-accent, var(--roc-ink, #252525));
  color: var(--roc-accent-foreground, var(--roc-paper, #fff));
}
.roc-ui-button.roc-ui-button-variant-secondary {
  background: var(--roc-marker, #efefef);
}
.roc-ui-button.roc-ui-button-variant-destructive {
  background: #b73838;
  color: white;
}
.roc-ui-button.roc-ui-button-variant-outline {
  border-color: var(--roc-line, #dedede);
  background: var(--roc-paper, #fff);
}
.roc-ui-button.roc-ui-button-variant-ghost,
.roc-ui-button.roc-ui-button-variant-link {
  background: transparent;
}
.roc-ui-button.roc-ui-button-variant-link {
  text-decoration: underline;
  text-underline-offset: 4px;
}
.roc-ui-button:hover:not(:disabled) {
  box-shadow: inset 0 0 0 100px #80808018;
}
.roc-ui-button.roc-ui-button-size-xs {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 26px;
  padding: 4px 8px;
  font-size: 11px;
}
.roc-ui-button.roc-ui-button-size-sm {
  --roc-button-radius: var(--roc-radius-compact);
  min-height: 32px;
  padding: 6px 12px;
}
.roc-ui-button.roc-ui-button-size-lg {
  min-height: 42px;
  padding: 11px 22px;
}
.roc-ui-button:is(
  .roc-ui-button-size-icon,
  .roc-ui-button-size-icon-xs,
  .roc-ui-button-size-icon-sm,
  .roc-ui-button-size-icon-lg
) {
  padding: 0;
  width: 36px;
  height: 36px;
}
.roc-ui-button.roc-ui-button-size-icon-xs {
  width: 26px;
  height: 26px;
  min-height: 26px;
}
.roc-ui-button.roc-ui-button-size-icon-sm {
  width: 32px;
  height: 32px;
  min-height: 32px;
}
.roc-ui-button.roc-ui-button-size-icon-lg {
  width: 42px;
  height: 42px;
}
.roc-ui-button[aria-busy="true"] {
  cursor: progress;
}

.roc-ui-button-label {
  display: inline-grid;
  align-items: center;
}
.roc-ui-button-label > span {
  grid-area: 1 / 1;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}
/* Pending swaps the label in place: the outgoing text lifts away blurred while
   the incoming text settles up from below. */
.roc-ui-button-label > span {
  transition:
    opacity var(--roc-motion-quick) ease-in-out,
    transform var(--roc-motion-quick) ease-in-out,
    filter var(--roc-motion-quick) ease-in-out;
}
.roc-ui-button-label > span[data-state="inactive"] {
  opacity: 0;
  filter: blur(var(--roc-motion-blur));
  pointer-events: none;
}
.roc-ui-button-label > span:first-child[data-state="inactive"] {
  transform: translateY(-4px);
}
.roc-ui-button-label > span:last-child[data-state="inactive"] {
  transform: translateY(4px);
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui-button-label > span {
    transition: none;
  }
}

@import "./tokens.css";
@import "./animation.css";
@import "./corners.css";
@import "./responsive.css";
/* Shared ROC foundations. No global reset or host stylesheet required. */
.roc-ui {
  box-sizing: border-box;
  font: inherit;
  font-family: var(--roc-font-body, inherit);
  font-size: var(--roc-text-body, 13px);
  color: var(--roc-ink, #252525);
}
.roc-ui *,
.roc-ui *::before,
.roc-ui *::after {
  box-sizing: border-box;
}
.roc-ui:focus-visible,
.roc-shadcn:focus-visible {
  outline: none;
  /* Draw the focus border inward, without changing the control's dimensions.
     Keep it visible when component hover or utility styles set box-shadow. */
  box-shadow: inset 0 0 0 2px var(--roc-focus, #737373) !important;
}
.roc-shadcn:focus {
  /* Imported utilities must not add an outer focus ring or its offset. */
  --roc-sh-tw-ring-shadow: 0 0 #0000 !important;
  --roc-sh-tw-ring-offset-shadow: 0 0 #0000 !important;
}
@media (forced-colors: active) {
  .roc-ui:focus-visible,
  .roc-shadcn:focus-visible {
    outline: 2px solid Highlight;
    outline-offset: -2px;
  }
}
.roc-ui:disabled,
.roc-ui[data-disabled] {
  opacity: 0.45;
  cursor: not-allowed;
}
/* Micro-motion scale, adapted from transitions.dev. Override on `.roc-ui`. */
:where(.roc-ui, .roc-shadcn) {
  --roc-motion-quick: 150ms;
  --roc-motion-fast: 250ms;
  --roc-motion-medium: 350ms;
  --roc-motion-ease: cubic-bezier(0.22, 1, 0.36, 1);
  --roc-motion-bounce: cubic-bezier(0.34, 1.36, 0.64, 1);
  --roc-motion-blur: 2px;
}
.roc-ui-icon,
.roc-ui > svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
  pointer-events: none;
}
.roc-ui-sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
/* Surfaces scale in from their anchor and settle back more quietly on exit. */
@keyframes roc-ui-pop-in {
  from {
    opacity: 0;
    transform: scale(var(--roc-pop-scale, 0.97));
  }
}
@keyframes roc-ui-pop-out {
  to {
    opacity: 0;
    transform: scale(var(--roc-pop-scale-out, 0.99));
  }
}
/* Side panels slide from their own edge; set --roc-slide-x / --roc-slide-y. */
@keyframes roc-ui-slide-in {
  from {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
@keyframes roc-ui-slide-out {
  to {
    translate: var(--roc-slide-x, 0) var(--roc-slide-y, 0);
  }
}
/* A swapped icon arrives small and blurred; messages settle up from below. */
@keyframes roc-ui-icon-in {
  from {
    opacity: 0;
    scale: 0.25;
    filter: blur(var(--roc-motion-blur));
  }
}
@keyframes roc-ui-rise-in {
  from {
    opacity: 0;
    translate: 0 4px;
    filter: blur(var(--roc-motion-blur));
  }
}
/* Invalid fields answer with one short horizontal shake. */
@keyframes roc-ui-shake {
  20% {
    translate: 6px 0;
  }
  50% {
    translate: -6px 0;
  }
  78% {
    translate: 4px 0;
  }
}
@keyframes roc-ui-dismiss {
  from {
    opacity: 1;
  }
  to {
    opacity: 0;
  }
}
@media (prefers-reduced-motion: reduce) {
  .roc-ui,
  .roc-ui::before,
  .roc-ui::after {
    transition-duration: 0s !important;
    animation-duration: 0.01ms !important;
  }
}

/* Shared design tokens for ROC practice cases. Hosts may override any --roc-* token. */
:where(:root) {
  --roc-ink: #252525;
  --roc-muted: #737373;
  --roc-paper: #ffffff;
  --roc-line: #e5e5e5;
  --roc-accent: #1a1a1a;
  --roc-accent-foreground: #ffffff;
  --roc-marker: #efefef;
  --roc-focus: #737373;
  --roc-font-body: ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --roc-font-heading: var(--roc-font-body);
  --roc-font-control: var(--roc-font-body);
  --roc-font-mono: ui-monospace, SFMono-Regular, Menlo, monospace;
  --roc-text-body: 13px;
  --roc-weight-control: 500;
  --roc-radius: 12px;
  --roc-space-1: 4px;
  --roc-space-2: 8px;
  --roc-space-3: 12px;
  --roc-space-4: 16px;
  --roc-space-6: 24px;
  --roc-space-8: 32px;
  --roc-control-height: 36px;
}

/* Animate UI owns presence. CSS keyframes must not compete with Motion's
   transforms/opacity or keep an exiting portal alive a second time. */
[data-roc-motion="animate-ui"][data-slot] {
  animation: none !important;
}
/* These parts use spring positions, so a CSS transition would lag the pointer. */
.roc-ui[data-slot="slider-thumb"],
.roc-ui[data-slot="slider-range"] {
  transition-property: background-color, border-color, box-shadow;
}
/* Static content stays still; interactive surfaces respond to state changes. */
:where(.roc-ui, .roc-shadcn):is(
  [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
  [data-slot="table-row"], [data-slot="sidebar-menu-button"]
) {
  transition: background-color 150ms ease-out, border-color 150ms ease-out,
    box-shadow 150ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
  :where(.roc-ui, .roc-shadcn):is(
    [data-slot="card"], [data-slot="item"], [data-slot="attachment"],
    [data-slot="table-row"], [data-slot="sidebar-menu-button"]
  ) { transition: none; }
}

/* Smooth squircle corners, following the visual treatment at https://corne.rs/.
   Native corner shaping keeps borders, shadows and overflowing content intact.
   Browsers without support retain the existing border-radius fallback. */
:where(
  [class^="roc-"],
  [class*=" roc-"],
  [class^="roc-"] *,
  [class*=" roc-"] *
) {
  /* ROC limits by role, informed by Apple's compact-control and surface guidance.
     These are ROC values, not platform-prescribed dimensions. Zero stays square. */
  --roc-radius-compact: min(var(--roc-radius, 9px), 8px);
  --roc-radius-control: min(var(--roc-radius, 9px), 10px);
  --roc-radius-popup: min(var(--roc-radius, 9px), 12px);
  --roc-radius-surface: min(var(--roc-radius, 12px), 20px);
}
@supports (corner-shape: squircle) {
  :where(
    [class^="roc-"],
    [class*=" roc-"],
    [class^="roc-"] *,
    [class*=" roc-"] *
  ) {
    corner-shape: var(--roc-corner-shape, squircle);
  }
}

/* Shared viewport constraints for portalled controls, including standalone consumers. */
:is(.roc-ui, .roc-shadcn)[data-slot]:is(
  [data-slot="popover-content"],
  [data-slot="hover-card-content"],
  [data-slot="tooltip-content"],
  [data-slot="select-content"],
  [data-slot="combobox-content"],
  [data-slot="dropdown-menu-content"],
  [data-slot="dropdown-menu-sub-content"],
  [data-slot="context-menu-content"],
  [data-slot="context-menu-sub-content"],
  [data-slot="menubar-content"],
  [data-slot="menubar-sub-content"]
) {
  max-inline-size: min(var(--available-width, calc(100vw - 24px)), calc(100vw - 24px));
  max-block-size: min(var(--available-height, calc(100dvh - 24px)), calc(100dvh - 24px));
  overflow: auto;
  overflow-wrap: anywhere;
  overscroll-behavior: contain;
}
@media (max-width: 640px), (pointer: coarse) {
  .roc-ui.roc-ui-button[data-slot],
  .roc-ui[data-slot="native-select"],
  .roc-shadcn[data-slot="select-trigger"] {
    min-height: 44px;
  }
  .roc-ui.roc-ui-button[data-size^="icon"] {
    width: 44px;
    height: 44px;
  }
  .roc-ui[data-slot="input"],
  .roc-ui[data-slot="textarea"],
  .roc-shadcn[data-slot="input-group-control"] {
    font-size: 16px;
  }
  .roc-ui[data-slot="input"],
  .roc-shadcn[data-slot="input-group"],
  .roc-ui[data-slot="slider"] {
    min-height: 44px;
  }
  .roc-shadcn[data-slot="input-group"] [data-slot="input-group-control"] {
    min-height: 42px;
  }
  .roc-sidebar-link,
  .roc-ui[data-slot="tabs-trigger"],
  .roc-ui[data-slot="toggle"],
  .roc-shadcn[data-slot="select-item"],
  .roc-shadcn[data-slot="combobox-item"] {
    min-height: 44px;
  }
  .roc-ui[data-slot="dropdown-menu-item"],
  .roc-ui[data-slot="dropdown-menu-checkbox-item"],
  .roc-ui[data-slot="dropdown-menu-radio-item"],
  .roc-shadcn[data-slot="context-menu-item"],
  .roc-shadcn[data-slot="menubar-item"] {
    min-height: 44px;
  }
}

@import "./ui-base.css";
.roc-ui[data-slot="dialog-overlay"] {
  position: fixed;
  inset: 0;
  z-index: 50;
  background: #00000030;
  animation: roc-ui-dismiss 160ms reverse;
}
.roc-ui[data-slot="dialog-overlay"][data-state="closed"] {
  animation: roc-ui-dismiss 160ms;
}
.roc-ui[data-slot="dialog-content"] {
  position: fixed;
  z-index: 51;
  left: 50%;
  top: 50%;
  translate: -50% -50%;
  display: grid;
  gap: 20px;
  width: min(480px, calc(100vw - 40px));
  max-height: calc(
    100dvh - max(24px, env(safe-area-inset-top), var(--roc-safe-top, 0px)) -
      max(24px, env(safe-area-inset-bottom), var(--roc-safe-bottom, 0px))
  );
  overflow: auto;
  padding: 24px;
  border: 1px solid var(--roc-line, #dedede);
  border-radius: var(--roc-radius-surface);
  background: var(--roc-paper, #fff);
  box-shadow: 0 16px 64px #00000018;
  transition:
    top 320ms cubic-bezier(0.22, 0.8, 0.25, 1),
    translate 320ms cubic-bezier(0.22, 0.8, 0.25, 1),
    width 320ms cubic-bezier(0.22, 0.8, 0.25, 1),
    border-radius 320ms;
  --roc-pop-scale: 0.96;
  --roc-pop-scale-out: 0.96;
  animation: roc-ui-pop-in var(--roc-motion-fast) var(--roc-motion-ease);
}
.roc-ui[data-slot="dialog-content"][data-state="closed"] {
  animation: roc-ui-pop-out var(--roc-motion-quick) var(--roc-motion-ease);
}
.roc-ui-dialog-dismiss {
  position: absolute;
  top: 15px;
  right: 15px;
  display: grid;
  place-items: center;
  width: 28px;
  height: 28px;
  padding: 4px;
  border: 0;
  border-radius: var(--roc-radius-compact);
  background: transparent;
  cursor: pointer;
}
.roc-ui[data-slot="dialog-header"] {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding-right: 18px;
}
.roc-ui[data-slot="dialog-title"] {
  margin: 0;
  font-size: 18px;
  font-weight: 550;
}
.roc-ui[data-slot="dialog-description"] {
  margin: 0;
  color: var(--roc-muted, #737373);
  line-height: 1.6;
}
.roc-ui[data-slot="dialog-footer"] {
  display: flex;
  justify-content: flex-end;
  flex-wrap: wrap;
  gap: 8px;
}
@media (max-width: 640px) {
  .roc-ui[data-slot="dialog-content"] {
    top: calc(
      100% - max(12px, env(safe-area-inset-bottom), var(--roc-safe-bottom, 0px))
    );
    translate: -50% -100%;
    width: calc(
      100vw - max(12px, env(safe-area-inset-left), var(--roc-safe-left, 0px)) -
        max(12px, env(safe-area-inset-right), var(--roc-safe-right, 0px))
    );
    padding: 22px;
  }
}
